{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.full_size_inv_avail as WITH wh_inv AS ( SELECT TRIM( UPPER( REVERSE( SUBSTRING( REVERSE(\"Item SkuCode\"), POSITION(\'-\' IN REVERSE(\"Item SkuCode\")) + 1 ) ) ) ) AS sku_group, UPPER( REVERSE( SUBSTRING( REVERSE(\"Item SkuCode\"), 1, POSITION(\'-\' IN REVERSE(\"Item SkuCode\")) - 1 ) ) ) AS raw_size, SUM(inventory) AS wh_qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = CURRENT_DATE AND facility IN (\'SAPL-WH2\', \'SAPL-WH1\', \'SAPL-NORTH-TAURU\') GROUP BY 1, 2 ), wh_inv_norm AS ( SELECT sku_group, CASE WHEN raw_size IS NULL OR TRIM(raw_size) = \'\' THEN \'L\' WHEN raw_size = \'01M\' THEN \'M\' WHEN raw_size = \'01XL\' THEN \'XL\' WHEN raw_size = \'06XL\' THEN \'6XL\' WHEN raw_size IN (\'XS\', \'S\', \'M\', \'L\', \'XL\') THEN raw_size WHEN raw_size IN (\'XXL\', \'2XL\', \'XXU\') THEN \'2XL\' WHEN raw_size IN (\'XXXL\', \'3XL\') THEN \'3XL\' WHEN raw_size IN (\'4XL\', \'5XL\', \'6XL\', \'7XL\', \'8XL\') THEN raw_size WHEN raw_size = \'28\' THEN \'XS\' WHEN raw_size = \'30\' THEN \'S\' WHEN raw_size = \'32\' THEN \'M\' WHEN raw_size = \'34\' THEN \'L\' WHEN raw_size = \'36\' THEN \'XL\' WHEN raw_size = \'38\' THEN \'2XL\' WHEN raw_size = \'40\' THEN \'3XL\' WHEN raw_size = \'42\' THEN \'4XL\' WHEN raw_size = \'44\' THEN \'5XL\' WHEN raw_size = \'46\' THEN \'6XL\' WHEN raw_size = \'48\' THEN \'7XL\' WHEN raw_size = \'50\' THEN \'8XL\' WHEN raw_size = \'39\' THEN \'2XL\' WHEN raw_size = \'41\' THEN \'4XL\' WHEN raw_size = \'43\' THEN \'5XL\' WHEN raw_size = \'45\' THEN \'6XL\' WHEN raw_size = \'1\' THEN \'XS\' WHEN raw_size = \'2\' THEN \'S\' WHEN raw_size = \'3\' THEN \'M\' WHEN raw_size = \'4\' THEN \'L\' WHEN raw_size = \'5\' THEN \'XL\' WHEN raw_size = \'6\' THEN \'2XL\' ELSE raw_size END AS size, wh_qty FROM wh_inv ), offline_sizes AS ( SELECT SKU_GROUP AS sku_group, \'XS\' AS size, COALESCE(XS_UNITS, 0) AS store_qty, COALESCE(JIT_XS_UNITS, 0) AS jit_qty FROM snitch_db.maplemonk.offline_master UNION ALL SELECT SKU_GROUP, \'S\', COALESCE(S_UNITS, 0), COALESCE(JIT_S_UNITS, 0) FROM snitch_db.maplemonk.offline_master UNION ALL SELECT SKU_GROUP, \'M\', COALESCE(M_UNITS, 0), COALESCE(JIT_M_UNITS, 0) FROM snitch_db.maplemonk.offline_master UNION ALL SELECT SKU_GROUP, \'L\', COALESCE(L_UNITS, 0), COALESCE(JIT_L_UNITS, 0) FROM snitch_db.maplemonk.offline_master UNION ALL SELECT SKU_GROUP, \'XL\', COALESCE(XL_UNITS, 0), COALESCE(JIT_XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master UNION ALL SELECT SKU_GROUP, \'2XL\', COALESCE(XXL_UNITS, 0), COALESCE(JIT_2XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master UNION ALL SELECT SKU_GROUP, \'3XL\', COALESCE(XL3_UNITS, 0), COALESCE(JIT_3XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master UNION ALL SELECT SKU_GROUP, \'4XL\', COALESCE(XL4_UNITS, 0), COALESCE(JIT_4XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master UNION ALL SELECT SKU_GROUP, \'5XL\', COALESCE(XL5_UNITS, 0), COALESCE(JIT_5XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master UNION ALL SELECT SKU_GROUP, \'6XL\', COALESCE(XL6_UNITS, 0), COALESCE(JIT_6XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master ), variant_exists AS ( SELECT DISTINCT TRIM( UPPER(REGEXP_REPLACE(value:sku::STRING, \'-[^-]+$\', \'\')) ) AS sku_group, TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) AS raw_size, CASE WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) = \'01M\' THEN \'M\' WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) = \'01XL\' THEN \'XL\' WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) = \'06XL\' THEN \'6XL\' WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) IN (\'XS\', \'S\', \'M\', \'L\', \'XL\') THEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) IN (\'XXL\', \'2XL\', \'XXU\') THEN \'2XL\' WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) IN (\'XXXL\', \'3XL\') THEN \'3XL\' WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) IN (\'4XL\', \'5XL\', \'6XL\', \'7XL\', \'8XL\') THEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) = \'28\' THEN \'XS\' WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) = \'30\' THEN \'S\' WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) = \'32\' THEN \'M\' WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) = \'34\' THEN \'L\' WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) = \'36\' THEN \'XL\' WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) = \'38\' THEN \'2XL\' WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) = \'40\' THEN \'3XL\' WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) = \'42\' THEN \'4XL\' WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) = \'44\' THEN \'5XL\' WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) = \'46\' THEN \'6XL\' WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) = \'48\' THEN \'7XL\' WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) = \'50\' THEN \'8XL\' WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) = \'39\' THEN \'2XL\' WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) = \'41\' THEN \'4XL\' WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) = \'43\' THEN \'5XL\' WHEN TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) = \'45\' THEN \'6XL\' ELSE null END AS size FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(INPUT => PARSE_JSON(variants)) AS value WHERE value:sku IS NOT NULL ), wh_by_size AS ( SELECT sku_group, size, SUM(wh_qty) AS wh_qty FROM wh_inv_norm GROUP BY 1, 2 ), offline_by_size AS ( SELECT upper(sku_group) sku_group, size, SUM(store_qty) AS store_qty, SUM(jit_qty) AS jit_qty FROM offline_sizes GROUP BY 1, 2 ), base AS ( SELECT upper(trim(sku_group)) sku_group, l1_category, category, meta1, meta2, meta3, upper(trim(size)) AS size, COALESCE(w.wh_qty, 0) AS wh_qty, COALESCE(o.store_qty, 0) AS store_qty, COALESCE(o.jit_qty, 0) AS jit_qty, ( COALESCE(o.store_qty, 0) + COALESCE(o.jit_qty, 0) ) AS store_plus_jit_qty, ( COALESCE(w.wh_qty, 0) + COALESCE(o.store_qty, 0) + COALESCE(o.jit_qty, 0) ) AS total_qty, CASE WHEN COALESCE(w.wh_qty, 0) > 0 THEN 1 ELSE 0 END AS wh_avail, CASE WHEN ( COALESCE(o.store_qty, 0) + COALESCE(o.jit_qty, 0) ) > 0 THEN 1 ELSE 0 END AS offline_avail, CASE WHEN ( COALESCE(w.wh_qty, 0) + COALESCE(o.store_qty, 0) + COALESCE(o.jit_qty, 0) ) > 0 THEN 1 ELSE 0 END AS overall_avail FROM wh_by_size w FULL OUTER JOIN offline_by_size o using(sku_group, size) left join snitch_db.maplemonk.meta_mapping_cogs_sku using(sku_group) ORDER BY 1, 2 ), req AS ( SELECT b.*, CASE WHEN v.sku_group IS NOT NULL THEN 1 ELSE 0 END AS variant_exists, CASE WHEN v.sku_group IS NULL THEN NULL WHEN UPPER(l1_category) IN (\'SNITCH\', \'LUXE\') AND size = \'XS\' THEN 10 WHEN UPPER(l1_category) IN (\'SNITCH\', \'LUXE\') AND size = \'S\' THEN 20 WHEN UPPER(l1_category) IN (\'SNITCH\', \'LUXE\') AND size = \'M\' THEN 30 WHEN UPPER(l1_category) IN (\'SNITCH\', \'LUXE\') AND size = \'L\' THEN 30 WHEN UPPER(l1_category) IN (\'SNITCH\', \'LUXE\') AND size = \'XL\' THEN 20 WHEN UPPER(l1_category) IN (\'SNITCH\', \'LUXE\') AND size = \'2XL\' THEN 10 WHEN UPPER(l1_category) = \'PLUS\' AND UPPER(category) IN (\'SHIRTS\', \'TSHIRTS\') AND size IN (\'3XL\', \'4XL\', \'5XL\', \'6XL\') THEN 20 WHEN UPPER(l1_category) = \'PLUS\' AND UPPER(category) IN (\'TROUSERS\', \'JEANS\') AND size = \'3XL\' THEN 30 WHEN UPPER(l1_category) = \'PLUS\' AND UPPER(category) IN (\'TROUSERS\', \'JEANS\') AND size = \'4XL\' THEN 30 WHEN UPPER(l1_category) = \'PLUS\' AND UPPER(category) IN (\'TROUSERS\', \'JEANS\') AND size IN (\'5XL\', \'6XL\') THEN 20 WHEN UPPER(l1_category) = \'PLUS\' AND UPPER(category) IN (\'TROUSERS\', \'JEANS\') AND size IN (\'7XL\', \'8XL\') THEN 10 ELSE NULL END AS required_qty FROM base b LEFT JOIN variant_exists v using(sku_group, size) ), online_flag AS ( SELECT sku_group, CASE WHEN MAX( CASE WHEN size = \'S\' AND wh_qty > 1 THEN 1 ELSE 0 END ) = 1 AND MAX( CASE WHEN size = \'M\' AND wh_qty > 1 THEN 1 ELSE 0 END ) = 1 AND MAX( CASE WHEN size = \'L\' AND wh_qty > 1 THEN 1 ELSE 0 END ) = 1 THEN \'Full Size Inv\' ELSE \'Not Full Size\' END AS wh_online_remark, CASE WHEN MAX( CASE WHEN size = \'S\' AND total_qty > 1 THEN 1 ELSE 0 END ) = 1 AND MAX( CASE WHEN size = \'M\' AND total_qty > 1 THEN 1 ELSE 0 END ) = 1 AND MAX( CASE WHEN size = \'L\' AND total_qty > 1 THEN 1 ELSE 0 END ) = 1 THEN \'Full Size Inv\' ELSE \'Not Full Size\' END AS total_online_remark FROM req GROUP BY 1 ), final_flag AS ( SELECT sku_group, CASE WHEN sum( CASE WHEN required_qty IS NOT NULL AND wh_qty >= required_qty THEN 1 ELSE 0 END ) >= 4 THEN \'Full Size Inv\' ELSE \'Not Full Size\' END AS wh_remark, CASE WHEN sum( CASE WHEN required_qty IS NOT NULL AND (store_qty + jit_qty) >= required_qty THEN 1 ELSE 0 END ) >= 4 THEN \'Full Size Inv\' ELSE \'Not Full Size\' END AS store_jit_remark, CASE WHEN sum( CASE WHEN required_qty IS NOT NULL AND total_qty >= required_qty THEN 1 ELSE 0 END ) >= 4 THEN \'Full Size Inv\' ELSE \'Not Full Size\' END AS total_remark FROM req WHERE required_qty IS NOT NULL GROUP BY 1 ), qty_totals AS ( SELECT sku_group, SUM(wh_qty) AS final_wh_qty, SUM(store_qty) AS final_store_qty, SUM(store_qty + jit_qty) AS final_store_jit_qty, SUM(total_qty) AS final_total_qty FROM req GROUP BY 1 ) SELECT f.sku_group, coalesce( mm.L1_CATEGORY, CASE WHEN LOWER(SKU_GROUP) LIKE \'4mbg%\' THEN \'plus_size\' WHEN LOWER(SKU_GROUP) LIKE \'r4mbg%\' THEN \'plus_size\' WHEN UPPER(SKU_GROUP) LIKE \'4MBGSS%\' THEN \'plus_size\' WHEN UPPER(SKU_GROUP) LIKE \'4MBGSR%\' THEN \'plus_size\' WHEN UPPER(SKU_GROUP) LIKE \'4MBGSD%\' THEN \'plus_size\' WHEN UPPER(SKU_GROUP) LIKE \'4MBGST%\' THEN \'plus_size\' WHEN UPPER(SKU_GROUP) LIKE \'4ML%\' THEN \'luxe\' WHEN UPPER(SKU_GROUP) LIKE \'4MTL%\' THEN \'luxe\' WHEN UPPER(SKU_GROUP) LIKE \'SH00%\' THEN \'long_tail\' WHEN UPPER(SKU_GROUP) LIKE \'4MBL%\' THEN \'long_tail\' WHEN UPPER(SKU_GROUP) LIKE \'4MHT%\' THEN \'long_tail\' WHEN UPPER(SKU_GROUP) LIKE \'4MCP%\' THEN \'long_tail\' WHEN UPPER(SKU_GROUP) LIKE \'4MBD%\' THEN \'long_tail\' WHEN UPPER(SKU_GROUP) LIKE \'SN%\' THEN \'long_tail\' WHEN UPPER(SKU_GROUP) LIKE \'SH%\' THEN \'long_tail\' WHEN UPPER(SKU_GROUP) LIKE \'4MSFC%\' THEN \'long_tail\' WHEN LOWER(sku_group) LIKE \'4lrn%\' THEN \'luxe\' WHEN LOWER(sku_group) LIKE \'4lpl%\' THEN \'luxe\' WHEN LOWER(sku_group) LIKE \'4ltr%\' THEN \'luxe\' WHEN LOWER(sku_group) LIKE \'4lch%\' THEN \'luxe\' WHEN LOWER(sku_group) LIKE \'4lje%\' THEN \'luxe\' WHEN LOWER(sku_group) LIKE \'4ljk%\' THEN \'luxe\' WHEN LOWER(sku_group) LIKE \'4lsw%\' THEN \'luxe\' WHEN LOWER(sku_group) LIKE \'4lhd%\' THEN \'luxe\' WHEN LOWER(sku_group) LIKE \'4los%\' THEN \'luxe\' WHEN LOWER(sku_group) LIKE \'4lsh%\' THEN \'luxe\' WHEN LOWER(sku_group) LIKE \'4lshs%\' THEN \'luxe\' WHEN LOWER(sku_group) LIKE \'4lsfs%\' THEN \'luxe\' WHEN LOWER(sku_group) LIKE \'4lbl%\' THEN \'luxe\' WHEN LOWER(sku_group) LIKE \'4lca%\' THEN \'luxe\' WHEN LOWER(sku_group) LIKE \'4lswt%\' THEN \'luxe\' WHEN LOWER(sku_group) LIKE \'4lcd%\' THEN \'luxe\' WHEN LOWER(sku_group) LIKE \'4ljo%\' THEN \'luxe\' WHEN LOWER(sku_group) LIKE \'4brn%\' THEN \'plus\' WHEN LOWER(sku_group) LIKE \'4bpl%\' THEN \'plus\' WHEN LOWER(sku_group) LIKE \'4btr%\' THEN \'plus\' WHEN LOWER(sku_group) LIKE \'4bch%\' THEN \'plus\' WHEN LOWER(sku_group) LIKE \'4bje%\' THEN \'plus\' WHEN LOWER(sku_group) LIKE \'4bjk%\' THEN \'plus\' WHEN LOWER(sku_group) LIKE \'4bsw%\' THEN \'plus\' WHEN LOWER(sku_group) LIKE \'4bhd%\' THEN \'plus\' WHEN LOWER(sku_group) LIKE \'4bos%\' THEN \'plus\' WHEN LOWER(sku_group) LIKE \'4bsh%\' THEN \'plus\' WHEN LOWER(sku_group) LIKE \'4bshs%\' THEN \'plus\' WHEN LOWER(sku_group) LIKE \'4bsfs%\' THEN \'plus\' WHEN LOWER(sku_group) LIKE \'4bbl%\' THEN \'plus\' WHEN LOWER(sku_group) LIKE \'4bca%\' THEN \'plus\' WHEN LOWER(sku_group) LIKE \'4bswt%